// Cross-implementation parity harness (roadmap step 4): the web scene graph
// must reproduce the desktop engine's world transforms exactly.
//
// The reference JSON is generated by tools/dump_world_transforms.py running
// the REAL desktop engine (glyphviz_core.compute_world_transforms) over the
// same CSV — regenerate it whenever either side's placement math changes.

import { describe, expect, it } from 'vitest'
import * as THREE from 'three'
import { buildScene } from './buildScene'
import { parseGvNodeCsv } from '../gv/nodeCsv'
import topologyExampleCsv from '../gv/fixtures/topology_example_gv_node.csv?raw'
import referenceRaw from '../gv/fixtures/topology_example_world_transforms.json?raw'

interface ReferenceEntry {
  id: number
  pos: [number, number, number]
  basis: [[number, number, number], [number, number, number], [number, number, number]]
}

const reference = JSON.parse(referenceRaw) as {
  source_csv: string
  base_scale: number
  nodes: ReferenceEntry[]
}

const TOLERANCE = 1e-6

describe('world-transform parity with the desktop engine', () => {
  const parsed = parseGvNodeCsv(topologyExampleCsv)
  const { root } = buildScene(parsed.nodes)
  root.updateMatrixWorld(true)

  it('covers every node in the fixture', () => {
    expect(parsed.errors).toEqual([])
    expect(reference.nodes).toHaveLength(parsed.nodes.length)
    expect(reference.base_scale).toBe(1)
  })

  for (const entry of reference.nodes) {
    it(`node ${entry.id} matches position and basis`, () => {
      const frame = root.getObjectByName(`gv:${entry.id}`)
      expect(frame, `frame for node ${entry.id}`).toBeDefined()

      const pos = new THREE.Vector3().setFromMatrixPosition(frame!.matrixWorld)
      expect(Math.abs(pos.x - entry.pos[0])).toBeLessThan(TOLERANCE)
      expect(Math.abs(pos.y - entry.pos[1])).toBeLessThan(TOLERANCE)
      expect(Math.abs(pos.z - entry.pos[2])).toBeLessThan(TOLERANCE)

      // Desktop world_basis rows/cols vs Three.js column-major Matrix3.
      const basis = new THREE.Matrix3().setFromMatrix4(frame!.matrixWorld)
      for (let r = 0; r < 3; r++) {
        for (let c = 0; c < 3; c++) {
          const actual = basis.elements[c * 3 + r]
          const expected = entry.basis[r][c]
          expect(
            Math.abs(actual - expected),
            `node ${entry.id} basis[${r}][${c}]: web ${actual} vs desktop ${expected}`,
          ).toBeLessThan(TOLERANCE)
        }
      }
    })
  }
})
